public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    int upper = desiredCapacity;
    if (desiredCapacity >= 1000) {
        upper = (int) (desiredCapacity * 1.11) + 1;
        if (upper % 2 == 0) {
            upper++;
        }
    }
    while (candidate <= upper) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }
    // If no prime found within the 11% range, return the upper bound
    return upper;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n == 2) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrt; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

