private void pop(final String descriptor){
    int i = 0;
    if (descriptor.charAt(0) == '('){
        i = 1;
        while (descriptor.charAt(i) != ')'){
            // skip array brackets
            while (descriptor.charAt(i) == '['){
                i++;
            }
            // skip object type
            if (descriptor.charAt(i) == 'L'){
                i++;
                while (descriptor.charAt(i) != ';'){
                    i++;
                }
                i++; // skip ';'
            }else{
                // primitive type
                i++;
            }
            // pop one type from stack
            pos--;
        }
        // skip ')'
        i++;
    }else{
        // single type descriptor
        while (descriptor.charAt(i) == '['){
            i++;
        }
        if (descriptor.charAt(i) == 'L'){
            i++;
            while (descriptor.charAt(i) != ';'){
                i++;
            }
            i++; // skip ';'
        }else{
            // primitive type
            i++;
        }
        // if not void, pop
        if (descriptor.charAt(i-1) != 'V'){
            pos--;
        }
    }
}

